def wrap(text, width):
    result = []
    paragraphs = text.split('\n')
    for para in paragraphs:
        raw_words = para.split()
        words = []
        for w in raw_words:
            if len(w) > width:
                for i in range(0, len(w), width):
                    words.append(w[i:i+width])
            else:
                words.append(w)
        if not words:
            result.append('')
            continue
        lines = []
        cur = words[0]
        for w in words[1:]:
            if len(cur) + 1 + len(w) <= width:
                cur += ' ' + w
            else:
                lines.append(cur)
                cur = w
        lines.append(cur)
        result.extend(lines)
    return result

